        console.log(
          chalk.green("Setup complete."),
        );
        console.log(
          chalk.gray("Restart your agent session for changes to take effect."),
        );
      }
    },
  );
} catch (err) {
  error(errors.failures.setupFailed, err);
  process.exit(EXIT_CODES.ERROR);

